let user=null, path=location.pathname, apps=[], file=null, cart={}, selectedStall=null;
const pendingWrites=new Map();
async function api(p,method='GET',body){
 const payload=body===undefined?undefined:JSON.stringify(body),write=method==='POST',fingerprint=[user?.id||'anonymous',p,payload].join(':');
 if(write&&!pendingWrites.has(fingerprint))pendingWrites.set(fingerprint,crypto.randomUUID());
 const r=await fetch('/api/v1/'+p,{method,headers:{'Content-Type':'application/json',...(write?{'Idempotency-Key':pendingWrites.get(fingerprint)}:{})},body:payload});
 let v;try{v=await r.json()}catch{throw Error('服务暂不可用，请重试；已提交的记录不会重复创建')}
 if(write&&(r.ok||r.status<500))pendingWrites.delete(fingerprint);
 if(!r.ok)throw Object.assign(new Error(v.error?.message||'请求失败'),{status:r.status,code:v.error?.code});return v.data;
}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const badge=s=>`<span class="badge">${esc(labels[s]||s)}</span>`,money=n=>'¥'+(Number(n||0)/100).toFixed(2),date=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—';
