function projectionCard(r){return `<article class="listitem"><div><h3>${esc(r.title||r.name||r.serviceName||r.domain||'校园服务')} ${r.status?serviceBadge(r.status):''}</h3><p>${esc(r.description||r.body||r.nextAction||r.sourceName||'')}</p><p class="muted">${esc(r.source||r.domain||r.type||'')}${r.dueAt?' · 截止 '+date(r.dueAt):''}${r.startsAt||r.start?' · '+date(r.startsAt||r.start):''}${r.end?' 至 '+date(r.end):''}</p></div><a class="btn" href="${esc(projectionLink(r))}">${esc(r.actionLabel||r.nextStep||'查看并办理')}${ico('arrow')}</a></article>`}
