 const h=await api('home');const available=(h.apps||apps).filter(a=>a.status==='ACTIVE');const recent=(h.recentUses||[]).map(r=>r.app||available.find(a=>a.id===r.appId)).filter(Boolean);const candidates=[...apps.filter(a=>a.favorite&&a.status==='ACTIVE'),...recent,...(h.recommendedApps||h.recommended||available)];const seen=new Set();const common=candidates.filter(a=>a&&a.status==='ACTIVE'&&!seen.has(a.id)&&seen.add(a.id)).slice(0,8);const counts=h.counts||{};
