async function projectionList(endpoint,title,description){let page=1,generation=0;$('#content').innerHTML=heading(title,description)+`<section class="card"><div class="filters"><input class="btn" id="projectionQuery" aria-label="搜索记录" placeholder="搜索记录"><select class="btn" id="projectionDomain" aria-label="来源筛选"><option value="">全部来源</option>${Object.entries(projectionDomains).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><select class="btn" id="projectionStatus" aria-label="状态筛选"><option value="">全部状态</option>${['PENDING','SUBMITTED','READY','ACCEPTED','PROCESSING','PREPARING','ACTIVE','ON_LOAN','APPROVED','ALLOCATED','REQUESTED','RETURNED','CONFIRMED','REGISTERED','COMPLETED','CANCELLED','REJECTED','CLOSED','EXPIRED','FAILED'].map(v=>`<option value="${v}">${esc(serviceLabels[v]||labels[v]||v)}</option>`).join('')}</select><button class="btn" id="projectionFilter">查询</button></div><div id="projectionRows"></div><div class="row" id="projectionPager"></div></section>`;const draw=async()=>{const token=++generation;$('#projectionRows').innerHTML='<div class="loading">正在加载记录…</div>';try{const payload=await api(endpoint+'?'+new URLSearchParams({page:String(page),pageSize:'20',domain:$('#projectionDomain').value,status:$('#projectionStatus').value,q:$('#projectionQuery').value}));if(token!==generation||!$('#projectionRows'))return;const rows=projectionRows(payload),meta=payload.meta||{total:rows.length,totalPages:1};$('#projectionRows').innerHTML=rows.map(projectionCard).join('')||'<div class="empty">暂无符合条件的记录。</div>';$('#projectionPager').innerHTML=`<span class="muted">共${meta.total}条 · 第${page}/${Math.max(1,meta.totalPages)}页</span><button class="btn" id="projectionPrev" ${page===1?'disabled':''}>上一页</button><button class="btn" id="projectionNext" ${page>=meta.totalPages?'disabled':''}>下一页</button>`;$('#projectionPrev').onclick=()=>{page--;draw()};$('#projectionNext').onclick=()=>{page++;draw()}}catch(e){if($('#projectionRows'))$('#projectionRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};const filter=()=>{page=1;draw()};$('#projectionFilter').onclick=filter;$('#projectionDomain').onchange=filter;$('#projectionStatus').onchange=filter;$('#projectionQuery').onkeydown=e=>{if(e.key==='Enter')filter()};draw()}
async function taskProjection(){const admin=path.startsWith('/admin/'),title=({'/admin/service-desk':'服务受理工作台','/admin/resources':'资源管理待办','/admin/applications':'部门审批待办'})[path]||(admin?'岗位待办':'我的待办');await projectionList(admin?'admin/tasks':'tasks',title,'待办由源业务状态生成；完成办理后自动消失。');if(admin){const scopes=(user.scopes||[]).filter(s=>s.roleId===user.activeRole),links=adminSections.filter(([p])=>allowedSection(p)&&!['','tasks','service-desk','resources','applications'].includes(p));$('#content .topline').insertAdjacentHTML('afterend',`<section class="card role-desk-summary"><p>当前身份：${esc(labels[user.activeRole]||user.activeRole)}</p><div class="row">${scopes.map(s=>`<span class="badge">${esc(s.resourceType)} · ${esc(s.resourceId)}</span>`).join('')||'<span class="muted">尚未分配业务范围，请联系管理员。</span>'}</div><nav class="filters role-desk-links" aria-label="已授权业务入口">${links.map(([p,t])=>`<a class="btn" href="/admin/${esc(p)}">${esc(t)}</a>`).join('')||'<p class="muted">暂无已授权模块。</p>'}</nav></section>`)}}
async function serviceCenter(){return projectionList('me/services','我的服务','汇总本人预约、借阅、订单及申请；点击进入对应业务详情。')}
async function adminBusinessDetail(){const match=path.match(/^\/admin\/(library\/(reservations|loans)|printing\/orders|dining\/orders)\/([^/]+)$/),domain=match[1],id=decodeURIComponent(match[3]),kind=domain==='library/reservations'?'libraryReservations':domain==='library/loans'?'libraryLoans':domain.startsWith('printing')?'printing':'dining';const rows=await api('admin/'+domain+'?'+new URLSearchParams({q:id,pageSize:'100'}));const recordData=(Array.isArray(rows)?rows:rows.records||[]).find(r=>r.id===id);if(!recordData)throw Error('记录不存在或不属于当前业务范围');$('#content').innerHTML=heading('业务办理详情','仅显示当前岗位范围内的源业务记录。',`<a class="btn" href="/admin/${domain}">返回列表</a>`)+`<section class="card">${record(recordData,kind,true)}</section>`}
const diningCategories={MISSING:'漏餐',WRONG:'错餐',QUALITY:'餐品质量',SERVICE:'服务问题'};
const diningFeedbackStatuses={OPEN:'待处理',PROCESSING:'处理中',RESOLVED:'已解决'};
