async function dining(){
 if(/^\/dining\/orders\/[^/]+\/feedback$/.test(path))return diningFeedbackPage();
 if(path.includes('orders'))return records('dining');
 const stalls=await api('dining/stalls');selectedStall=stalls.find(s=>path.endsWith(s.id))||stalls[0];cart={};$('#content').innerHTML=heading('智慧食堂','堂食自取 · 单档口下单 · 仅支持今天和明天取餐',`<a href="/dining/orders" class="btn">我的餐单</a>`)+`<div class="filters">${stalls.map(s=>`<a href="/dining/stalls/${esc(s.id)}" class="btn ${s.id===selectedStall?.id?'selected':''}">${esc(s.name)}</a>`).join('')}</div><div id="menu"></div>`;
 if(!selectedStall){$('#menu').innerHTML='<div class="card empty">暂无开放档口。</div>';return}
 const menu=await api('dining/stalls/'+selectedStall.id+'/menu'),today=new Date(Date.now()+28800000).toISOString().slice(0,10),tomorrow=new Date(Date.now()+86400000+28800000).toISOString().slice(0,10);
 const isOpen=(day,slot)=>new Date(day+'T'+(slot==='LUNCH'?'13:30':'19:30')+':00+08:00').getTime()-30*60000>Date.now();
 const defaultDay=['LUNCH','DINNER'].some(s=>isOpen(today,s))?today:tomorrow;
 $('#menu').innerHTML=`<div class="grid two">${menu.map(p=>`<article class="card"><div class="row"><div class="iconbox teal">${ico('dining')}</div><h3>${esc(p.name)}</h3></div><p>${esc(p.description||'校内档口自取，以下为演示菜品')}</p><div class="row"><b>${money(p.priceCents)}</b><span class="muted">库存以提交时的所选时段为准</span><label class="meal-quantity">份数 <input type="number" min="0" max="10" value="0" data-product="${esc(p.variantId||p.id)}" aria-label="${esc(p.name)}份数"></label></div></article>`).join('')||'<div class="empty">该档口暂无在售菜品。</div>'}</div><form id="diningForm" class="card form" style="margin-top:24px"><h2>确认取餐与付款方式</h2><div class="grid two"><label class="field">取餐日期（北京时间）<input name="pickupDate" type="date" min="${today}" max="${tomorrow}" value="${defaultDay}" required></label><label class="field">取餐时段<select name="pickupSlot"><option value="LUNCH">午餐 11:00—13:30</option><option value="DINNER">晚餐 17:00—19:30</option></select></label></div><p class="muted" id="diningSlotNotice">取餐时段结束前30分钟停止接单，按服务器最终校验。</p><div class="field"><label for="diningPaymentMode">付款方式</label><select id="diningPaymentMode" name="paymentMode"><option value="OFFLINE">到店付款</option><option value="SIMULATED">模拟付款 · 未发生真实收款</option></select></div><p class="service-notice" id="diningPaymentNotice">到店付款由商户确认收款后核销，不发生线上扣款。</p><p>餐单金额由服务器按实际在售价格计算；每规格1~10份，整单最多20份。</p><button class="btn primary" id="diningSubmit">提交餐单</button><p id="diningError" role="alert"></p></form>`;
 const form=$('#diningForm'),day=form.querySelector('[name=pickupDate]'),slot=form.querySelector('[name=pickupSlot]'),payment=form.querySelector('[name=paymentMode]');
 const updateSlots=()=>{for(const option of slot.options)option.disabled=!isOpen(day.value,option.value)||![today,tomorrow].includes(day.value);if(slot.selectedOptions[0]?.disabled)slot.value=[...slot.options].find(o=>!o.disabled)?.value||'';$('#diningSubmit').disabled=!slot.value;$('#diningSlotNotice').textContent=slot.value?'取餐时段结束前30分钟停止接单，按服务器最终校验。':'所选日期没有可接单时段，请选择明天。'};day.onchange=updateSlots;payment.onchange=()=>{$('#diningPaymentNotice').textContent=payment.value==='SIMULATED'?'模拟付款，未发生真实收款。此订单不计入真实收入，也不能作为付款凭证。':'到店付款由商户确认收款后核销，不发生线上扣款。'};updateSlots();
 form.onsubmit=async e=>{e.preventDefault();const submit=$('#diningSubmit');submit.disabled=true;try{if(![today,tomorrow].includes(day.value)||!isOpen(day.value,slot.value))throw Error('取餐日期或时段已截止，请重新选择');const items=[...document.querySelectorAll('[data-product]')].map(el=>({variantId:el.dataset.product,quantity:Number(el.value)})).filter(x=>x.quantity>0);if(!items.length)throw Error('请至少选择一份餐品');if(items.some(x=>!Number.isInteger(x.quantity)||x.quantity>10)||items.reduce((s,x)=>s+x.quantity,0)>20)throw Error('每种餐品1~10份，整单最多20份');await api('dining/orders','POST',{...Object.fromEntries(new FormData(form)),stallId:selectedStall.id,items});toast('餐单已提交');go('/dining/orders')}catch(e){$('#diningError').className='error';$('#diningError').textContent=e.message;updateSlots()}};
}
function feedbackHistoryCard(row){return `<article class="feedback-record"><div class="topline"><h3>${esc(diningCategories[row.category]||row.category)}</h3><span class="service-status">${esc(diningFeedbackStatuses[row.status]||row.status)}</span></div><p class="feedback-body">${esc(row.body)}</p><p class="muted">提交时间 ${date(row.createdAt)}</p><section class="feedback-replies" aria-label="处理记录">${(row.replies||[]).map(reply=>`<div><p class="muted">服务人员回复 · ${date(reply.createdAt)}</p><p class="feedback-body">${esc(reply.body)}</p></div>`).join('')||'<p class="muted">尚无处理回复。</p>'}</section></article>`}
async function diningFeedbackPage(){const orderId=decodeURIComponent(path.split('/')[3]);await api('dining/orders/'+encodeURIComponent(orderId));$('#content').innerHTML=heading('餐饮反馈','反馈仅对本人和具有办理范围的工作人员可见。',`<a class="btn" href="/dining/orders/${esc(orderId)}">返回餐单详情</a>`)+`<section class="card" id="diningFeedback"></section>`;await mountDiningFeedback(orderId,$('#diningFeedback'))}
async function mountDiningFeedback(orderId,container){container.innerHTML='<div class="loading">正在加载反馈记录…</div>';try{const rows=await api('dining/orders/'+encodeURIComponent(orderId)+'/feedback');if(!container.isConnected)return;const active=rows.some(r=>['OPEN','PROCESSING'].includes(r.status));container.innerHTML=`<h2>投诉与反馈</h2><p>如遇漏餐、错餐、质量或服务问题，请描述具体情况。这里不发起自动退款。</p><div id="diningFeedbackHistory">${rows.map(feedbackHistoryCard).join('')||'<div class="empty">此餐单暂无反馈记录。</div>'}</div>${active?'<p class="service-notice">此餐单已有正在处理的反馈，请等待服务人员回复。解决后可提交新的问题。</p>':`<form id="diningFeedbackForm"><label class="field">问题类别<select name="category">${Object.entries(diningCategories).map(([code,label])=>`<option value="${code}">${label}</option>`).join('')}</select></label><label class="field">问题说明<textarea name="body" required minlength="1" maxlength="3000" rows="5" placeholder="请说明餐品、问题及发生情况，请勿填写无关敏感资料。"></textarea></label><button class="btn primary">提交反馈</button><p role="alert" id="diningFeedbackError"></p></form>`}<button class="btn" type="button" id="refreshDiningFeedback" style="margin-top:16px">刷新处理记录</button>`;$('#refreshDiningFeedback').onclick=()=>mountDiningFeedback(orderId,container);const form=$('#diningFeedbackForm');if(form)form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');btn.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(!data.body.trim())throw Error('请填写问题说明');await api('dining/orders/'+encodeURIComponent(orderId)+'/feedback','POST',data);toast('反馈已提交');await mountDiningFeedback(orderId,container)}catch(err){const alert=$('#diningFeedbackError');alert.className='error';alert.textContent=err.message;btn.disabled=false}}}catch(e){if(container.isConnected)container.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function diningFeedbackAdmin(){let page=1,generation=0;$('#content').innerHTML=adminHeading('dining/feedback')+heading('餐饮反馈处理','仅处理本人档口或已授权服务范围内的反馈。')+`<section class="card"><form class="filters" id="feedbackFilter"><input class="btn" id="feedbackQuery" maxlength="100" aria-label="搜索反馈" placeholder="搜索编号或问题说明"><select class="btn" id="feedbackStatus" aria-label="处理状态"><option value="">全部状态</option>${Object.entries(diningFeedbackStatuses).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button class="btn">查询</button></form><div id="feedbackAdminRows"></div><div class="row" id="feedbackAdminPager"></div></section>`;
 const draw=async()=>{const token=++generation;$('#feedbackAdminRows').innerHTML='<div class="loading">正在加载反馈…</div>';try{const response=await fetch('/api/v1/admin/dining/feedback?'+new URLSearchParams({page:String(page),pageSize:'20',q:$('#feedbackQuery').value.trim(),status:$('#feedbackStatus').value})),payload=await response.json();if(!response.ok)throw Error(payload.error?.message||'无法加载反馈');if(token!==generation||!$('#feedbackAdminRows'))return;const rows=payload.data||[],meta=payload.meta||{total:rows.length,pageSize:20},pages=Math.max(1,Math.ceil(meta.total/(meta.pageSize||20)));$('#feedbackAdminRows').innerHTML=rows.map(row=>`<section class="feedback-admin-record">${feedbackHistoryCard(row)}<p class="muted">餐单 ${esc(row.orderId)} · 反馈 ${esc(row.id)}</p>${row.status!=='RESOLVED'?`<form class="feedback-reply-form" data-feedback-id="${esc(row.id)}"><label class="field">处理回复<textarea name="body" rows="3" maxlength="3000" required placeholder="说明处理进度或最终解决结果"></textarea></label><div class="row"><button class="btn" name="action" value="reply">回复并继续处理</button><button class="btn primary" name="action" value="resolve">回复并标为解决</button></div><p role="alert"></p></form>`:''}</section>`).join('')||'<div class="empty">暂无匹配反馈。</div>';$('#feedbackAdminPager').innerHTML=`<span class="muted">共${meta.total}条 · 第${page}/${pages}页</span><button class="btn" id="feedbackPrev" ${page<=1?'disabled':''}>上一页</button><button class="btn" id="feedbackNext" ${page>=pages?'disabled':''}>下一页</button>`;$('#feedbackPrev').onclick=()=>{page--;draw()};$('#feedbackNext').onclick=()=>{page++;draw()};document.querySelectorAll('.feedback-reply-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const row=rows.find(r=>r.id===form.dataset.feedbackId),body=new FormData(form).get('body').trim(),action=e.submitter?.value||'reply',buttons=[...form.querySelectorAll('button')],error=form.querySelector('[role=alert]');if(!body){error.className='error';error.textContent='请填写处理回复';return}if(action==='resolve'&&!await askConfirm('确认已经给出解决结果并结束此反馈？'))return;buttons.forEach(b=>b.disabled=true);try{await api('admin/feedback/'+row.id+'/'+action,'POST',{body,version:row.version});toast(action==='resolve'?'反馈已解决':'回复已保存');draw()}catch(e){error.className='error';error.textContent=e.message;buttons.forEach(b=>b.disabled=false)}})}catch(e){if($('#feedbackAdminRows'))$('#feedbackAdminRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};$('#feedbackFilter').onsubmit=e=>{e.preventDefault();page=1;draw()};$('#feedbackStatus').onchange=()=>{page=1;draw()};draw();
}
adminSections.push(['tasks','岗位待办'],['service-desk','服务受理工作台'],['resources','资源工作台'],['applications','部门审批工作台'],['dining/feedback/summary','餐饮反馈汇总'],['guides','版本化办事指南'],['rules','服务规则版本'],['connections','连接管理'],['system/health','系统健康']);
const guideFields={conditions:'适用条件',materials:'所需材料',steps:'办理步骤',contact:'联系方式',location:'办理地点',processingTime:'办理时限',fees:'费用说明'};
function guideVersionBody(v){return Object.entries(guideFields).map(([key,label])=>`<section class="guide-section"><h3>${label}</h3><p>${esc(v?.[key]||'未提供')}</p></section>`).join('')+`<p class="muted">版本${v?.version||'—'} · 生效 ${date(v?.validFrom)}${v?.validTo?' · 到期 '+date(v.validTo):' · 长期有效'}</p>`}
async function guidesPage(){const id=path.split('/')[2];if(id){const g=await api('guides/'+encodeURIComponent(id));$('#content').innerHTML=heading(esc(g.title),'负责人 '+esc(g.ownerName||'负责老师')+' · 负责部门 '+esc(g.departmentName||'负责部门'),'<a class="btn" href="/guides">返回指南</a>')+`<article class="card">${g.expired?'<p class="error">此版本已到期，办理前请联系负责部门确认。</p>':''}${guideVersionBody(g.currentVersion)}${g.entryAvailable&&!g.expired?`<a class="btn primary" href="${esc(g.currentVersion.entryPath)}">进入对应服务</a>`:'<button class="btn" disabled>当前办理入口不可用</button>'}</article>`;return}$('#content').innerHTML=heading('办事指南','查询已发布的办理条件、材料、步骤与有效版本。')+`<section class="card"><form class="filters" id="guideSearch"><input class="btn" id="guideQuery" maxlength="100" placeholder="搜索事项或材料" aria-label="搜索指南"><button class="btn">搜索</button></form><div id="guideRows"></div></section>`;let generation=0;const draw=async()=>{const token=++generation;$('#guideRows').innerHTML='<div class="loading">正在加载指南…</div>';try{const rows=await api('guides?q='+encodeURIComponent($('#guideQuery').value));if(token!==generation)return;$('#guideRows').innerHTML=rows.map(g=>`<a class="listitem" href="/guides/${esc(g.id)}"><div><h3>${esc(g.title)} ${g.expired?badge('已到期'):badge('已发布')}</h3><p>${esc(g.currentVersion?.conditions||'')}</p><span class="muted">当前版本${g.currentVersion?.version||'—'} · ${esc(g.currentVersion?.processingTime||'')}</span></div>${ico('arrow')}</a>`).join('')||'<div class="empty">暂无匹配的已发布指南。</div>'}catch(e){$('#guideRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};$('#guideSearch').onsubmit=e=>{e.preventDefault();draw()};draw()}
async function guidesAdmin(){const [rows,options]=await Promise.all([api('admin/guides'),api('admin/guides/options')]);const choice=(items,selected,labelKey,empty)=>`<option value="">${empty}</option>${items.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x[labelKey])}</option>`).join('')}${selected&&!items.some(x=>x.id===selected)?`<option value="${esc(selected)}" selected>原负责人或部门（当前不可选，请重新选择）</option>`:''}`;$('#content').innerHTML=adminHeading('guides')+heading('版本化办事指南','编辑生成草稿，预览确认后发布；保留历史版本。')+`<section class="card"><button class="btn primary" id="guideNew">新增指南草稿</button>${rows.map(g=>`<article class="listitem"><div><h3>${esc(g.title)} ${badge(g.status==='PUBLISHED'?'已发布':'草稿')}</h3><p>当前生效版本 ${g.currentVersion?.version||'无'} · 负责部门 ${esc(options.departments.find(d=>d.id===g.ownerDepartmentId)?.name||'待重新分配')}</p><p class="muted">${esc(g.id)}</p></div><div class="row"><button class="btn" data-guide-edit="${esc(g.id)}">修订草稿</button><button class="btn" data-guide-versions="${esc(g.id)}">预览与版本记录</button></div></article>`).join('')||'<div class="empty">暂无指南。</div>'}</section><div id="guideEditor"></div>`;const editor=$('#guideEditor');
 const edit=g=>{const v=g?.versions?.find(x=>x.status==='DRAFT')||g?.currentVersion||{},available=apps.filter(a=>a.status==='ACTIVE'&&a.internalPath);editor.innerHTML=`<form class="card form" id="guideForm"><h2>${g?'修订':'新增'}草稿</h2><label class="field">指南标题<input name="title" required maxlength="200" value="${esc(v.title||g?.title||'')}"></label><label class="field">对应服务<select name="serviceId" required><option value="">请选择已启用服务</option>${available.map(a=>`<option value="${esc(a.id)}" ${(v.serviceId||g?.serviceId)===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label class="field">负责部门<select name="ownerDepartmentId" required>${choice(options.departments||[],v.ownerDepartmentId||g?.ownerDepartmentId||user.organizationId,'name','请选择负责部门')}</select></label><label class="field">负责人<select name="ownerId" required>${choice(options.owners||[],v.ownerId||g?.ownerId||user.id,'displayName','请选择负责人')}</select></label>${Object.entries(guideFields).map(([key,label])=>`<label class="field">${label}<textarea name="${key}" rows="${key==='steps'?5:2}" required maxlength="${key==='steps'?10000:key==='conditions'||key==='materials'?3000:300}">${esc(v[key]||'')}</textarea></label>`).join('')}<label class="field">办理入口<input name="entryPath" required maxlength="200" value="${esc(v.entryPath||'')}" placeholder="选择服务后自动填入"></label><label class="field">生效时间（北京时间）<input name="validFrom" type="datetime-local" required value="${new Date((v.validFrom?Date.parse(v.validFrom):Date.now())+28800000).toISOString().slice(0,16)}"></label><label class="field">到期时间（可空，北京时间）<input name="validTo" type="datetime-local" value="${v.validTo?new Date(Date.parse(v.validTo)+28800000).toISOString().slice(0,16):''}"></label><button class="btn primary">保存新草稿版本</button><p role="alert" id="guideError"></p></form>`;const form=$('#guideForm');form.elements.serviceId.onchange=()=>{const app=available.find(a=>a.id===form.elements.serviceId.value);if(app)form.elements.entryPath.value=app.internalPath};form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');btn.disabled=true;try{const body=Object.fromEntries(new FormData(form));for(const key of ['validFrom','validTo'])body[key]=body[key]?new Date(body[key]+':00+08:00').toISOString():null;await api('admin/guides'+(g?'/'+g.id:''),g?'PATCH':'POST',body);toast('草稿已保存，尚未发布');guidesAdmin()}catch(e){$('#guideError').className='error';$('#guideError').textContent=e.message;btn.disabled=false}};editor.scrollIntoView({behavior:'smooth'})};
 const versions=g=>{editor.innerHTML=`<section class="card"><h2>${esc(g.title)} · 版本预览</h2>${(g.versions||[]).map(v=>`<article class="version-preview"><div class="topline"><h3>版本${v.version} ${badge(v.status==='DRAFT'?'草稿':'已发布')}</h3>${v.status==='DRAFT'?`<button class="btn primary" data-guide-publish="${esc(v.id)}">确认发布此版本</button>`:''}</div>${guideVersionBody(v)}<details><summary>与当前生效版本比较</summary><div class="version-diff">${Object.entries(guideFields).filter(([k])=>v[k]!==g.currentVersion?.[k]).map(([k,label])=>`<section><h4>${label}</h4><p class="muted">当前：${esc(g.currentVersion?.[k]||'无')}</p><p>草稿：${esc(v[k])}</p></section>`).join('')||'<p>以上正文与当前版本一致。</p>'}</div></details></article>`).join('')||'<div class="empty">暂无版本。</div>'}</section>`;editor.querySelectorAll('[data-guide-publish]').forEach(btn=>btn.onclick=async()=>{if(!await askConfirm('确认发布预览中的版本？现行办理指南将切换至该版本，历史版本保留。'))return;btn.disabled=true;try{await api('admin/guides/'+g.id+'/publish','POST',{versionId:btn.dataset.guidePublish});toast('指南版本已发布');guidesAdmin()}catch(e){toast(e.message);btn.disabled=false}});editor.scrollIntoView({behavior:'smooth'})};$('#guideNew').onclick=()=>edit(null);document.querySelectorAll('[data-guide-edit]').forEach(btn=>btn.onclick=()=>edit(rows.find(g=>g.id===btn.dataset.guideEdit)));document.querySelectorAll('[data-guide-versions]').forEach(btn=>btn.onclick=()=>versions(rows.find(g=>g.id===btn.dataset.guideVersions)))}
async function rulesAdmin(){const rows=await api('admin/rules'),points=await api('printing/points');$('#content').innerHTML=adminHeading('rules')+heading('服务规则版本','当前开放打印价格白名单配置；新草稿须确认后立即生效，旧订单保留价格快照。')+`<section class="card"><form class="form" id="ruleForm"><h2>新增打印价格草稿</h2><label class="field">打印点<select name="resourceId" required>${points.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><div class="grid two">${[['bwPerSide','黑白每印面'],['colorPerSide','彩色每印面'],['staplePerCopy','每份装订']].map(([key,label])=>`<label class="field">${label}（分）<input name="${key}" type="number" min="0" max="100000" step="1" required value="${key==='bwPerSide'?20:100}"></label>`).join('')}</div><p>只保存白名单整数分价格，发布后立即生效；不修改已有订单。</p><button class="btn primary">保存草稿并查看差异</button><p id="ruleError" role="alert"></p></form></section><section id="rulePreview"></section><section class="card" style="margin-top:24px"><h2>规则与版本</h2>${rows.map(r=>{const published=r.versions.find(v=>v.status==='PUBLISHED');return `<article class="version-preview"><h3>${esc(points.find(p=>p.id===r.resourceId)?.name||r.resourceId)}</h3>${r.versions.map(v=>`<section class="rule-version"><h4>版本${v.version} · ${esc(v.status==='DRAFT'?'草稿':'已发布')} · ${date(v.effectiveAt)}</h4><div>${Object.entries(v.config).map(([k,n])=>`<p>${esc({bwPerSide:'黑白每印面',colorPerSide:'彩色每印面',staplePerCopy:'每份装订'}[k]||k)}：${money(n)}${v.status==='DRAFT'?'（当前 '+money(published?.config?.[k]||0)+'）':''}</p>`).join('')}</div>${v.status==='DRAFT'?`<button class="btn primary" data-rule-publish="${esc(v.id)}" data-rule-id="${esc(r.id)}">确认差异并立即发布</button>`:''}</section>`).join('')}</article>`}).join('')||'<p class="empty">暂无规则版本。</p>'}</section>`;$('#ruleForm').onsubmit=async e=>{e.preventDefault();const form=e.target,btn=form.querySelector('button');btn.disabled=true;try{const d=Object.fromEntries(new FormData(form)),config=Object.fromEntries(['bwPerSide','colorPerSide','staplePerCopy'].map(k=>[k,Number(d[k])])),draft=await api('admin/rules','POST',{type:'PRINT_PRICE',resourceId:d.resourceId,config});$('#rulePreview').innerHTML=`<section class="card" style="margin-top:24px"><h2>草稿版本${draft.version} · 发布前确认</h2>${draft.diff.map(d=>`<p>${esc(d.key)}：${d.before===null?'无现行版本':money(d.before)} → ${money(d.after)}</p>`).join('')}<button class="btn primary" id="publishSavedRule">确认以上差异并立即发布</button></section>`;$('#publishSavedRule').onclick=()=>publish(draft.ruleId,draft.id,$('#publishSavedRule'));$('#rulePreview').scrollIntoView({behavior:'smooth'})}catch(e){$('#ruleError').className='error';$('#ruleError').textContent=e.message}finally{btn.disabled=false}};const publish=async(ruleId,versionId,btn)=>{if(!await askConfirm('确认打印价格立即生效？新订单将使用新价格，旧订单仍使用原快照。'))return;btn.disabled=true;try{await api('admin/rules/'+encodeURIComponent(ruleId).replace(/%3A/gi,':')+'/publish','POST',{versionId});toast('价格规则已发布');rulesAdmin()}catch(e){toast(e.message);btn.disabled=false}};document.querySelectorAll('[data-rule-publish]').forEach(btn=>btn.onclick=()=>publish(btn.dataset.ruleId,btn.dataset.rulePublish,btn))}
async function connectionsAdmin(){const rows=await api('admin/connections');$('#content').innerHTML=adminHeading('connections')+heading('外部连接管理','这里只保存非秘密配置、执行本地配置校验；不会宣称真实连接成功。')+`<p class="service-notice">密钥仅配置在服务器环境变量。切换TEST或LIVE不代表已经连接，不在此填写Secret、Token或账号密码。</p><section class="card">${rows.map(r=>`<article class="listitem"><div><h3>${esc(r.name)} ${badge(r.mode)}</h3><p>${esc(r.provider)} · ${r.enabled?'已启用配置':'未启用配置'} · ${r.configured?'环境配置存在':'环境配置未完整'}</p><p>真实连接：未验证 · 最近校验 ${date(r.lastTestAt)}</p><p class="muted">${esc(r.lastError||r.notice||'')}</p></div><div class="row"><button class="btn" data-connection-edit="${esc(r.id)}">编辑非秘密配置</button><button class="btn" data-connection-test="${esc(r.id)}">本地配置校验</button></div></article>`).join('')}</section><div id="connectionEditor"></div><div id="connectionTestResult" aria-live="polite"></div>`;const editor=$('#connectionEditor');document.querySelectorAll('[data-connection-edit]').forEach(btn=>btn.onclick=()=>{const r=rows.find(r=>r.id===btn.dataset.connectionEdit);editor.innerHTML=`<form class="card form" id="connectionForm" style="margin-top:24px"><h2>${esc(r.provider)}非秘密配置</h2><label class="field">名称<input name="name" required maxlength="100" value="${esc(r.name)}"></label><label class="field">模式<select name="mode">${['DEMO','MANUAL','TEST','LIVE'].map(m=>`<option ${r.mode===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="field">启用配置<select name="enabled"><option value="false" ${!r.enabled?'selected':''}>停用</option><option value="true" ${r.enabled?'selected':''}>启用</option></select></label><label class="field">负责人账号编号（可空）<input name="ownerId" value="${esc(r.ownerId||'')}"></label><label class="field">服务地址（不得含凭证、查询参数）<input name="baseUrl" type="url" value="${esc(r.settings?.baseUrl||'')}" placeholder="https://service.example.edu"></label><label class="field">协议名称（可空）<input name="authProtocol" maxlength="50" value="${esc(r.settings?.authProtocol||'')}"></label><button class="btn primary">保存配置</button><p id="connectionError" role="alert"></p></form>`;$('#connectionForm').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const d=Object.fromEntries(new FormData(form)),settings={};if(d.baseUrl)settings.baseUrl=d.baseUrl;if(d.authProtocol)settings.authProtocol=d.authProtocol;await api('admin/connections/'+r.id,'PATCH',{provider:r.provider,name:d.name,mode:d.mode,enabled:d.enabled==='true',ownerId:d.ownerId||null,settings,version:r.version});toast('非秘密配置已保存，真实连接仍未验证');connectionsAdmin()}catch(e){$('#connectionError').className='error';$('#connectionError').textContent=e.message;button.disabled=false}};editor.scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-connection-test]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{const r=await api('admin/connections/'+btn.dataset.connectionTest+'/test','POST',{});$('#connectionTestResult').innerHTML=`<section class="card" style="margin-top:24px"><h2>本地配置校验结果</h2><p>${esc(r.summary)}</p><p>提供方 ${esc(r.provider)} · 模式 ${esc(r.mode)}</p><p class="service-notice">真实连接未验证；此结果不是企微、支付或设备连接成功回执。</p>${r.missingConfiguration?.length?`<p>缺少环境配置：${esc(r.missingConfiguration.join('、'))}</p>`:''}</section>`}catch(e){$('#connectionTestResult').innerHTML=`<div class="error">${esc(e.message)}</div>`}finally{btn.disabled=false}})}
async function healthAdmin(){const health=await api('admin/system/health'),flags=await api('admin/feature-flags');$('#content').innerHTML=adminHeading('system/health')+heading('系统健康与新单开关','健康检查不等于生产验收；暂停新单不影响已有业务继续处理。',`<button class="btn" id="reloadSystemHealth">重新检查</button>`)+`<div class="grid two"><section class="card"><h2>应用与数据库</h2><p>版本 ${esc(health.version)} · 环境 ${esc(health.environment)}</p><p>数据库快速检查：${esc(health.database?.quickCheck)}</p><p>外键错误：${health.database?.foreignKeyErrors??'未知'}</p></section><section class="card"><h2>Worker</h2><p>状态：${esc(({HEALTHY:'正常',STALE:'心跳过期',UNKNOWN:'尚无心跳'})[health.worker?.status]||health.worker?.status)}</p><p>最近心跳 ${date(health.worker?.lastHeartbeat)}</p></section></div><section class="card" style="margin-top:24px"><h2>受理新单开关</h2>${flags.map(flag=>`<article class="listitem"><div><h3>${esc({'library.reservations.create':'图书新预约','printing.orders.create':'打印新订单','dining.orders.create':'食堂新订单'}[flag.code]||flag.code)}</h3><p>${flag.enabled?'正在受理新单':'暂停受理新单；历史业务继续办理'}</p></div><button class="btn ${flag.enabled?'danger':''}" data-feature-flag="${esc(flag.code)}" data-enabled="${flag.enabled?'false':'true'}">${flag.enabled?'暂停新单':'恢复新单'}</button></article>`).join('')}</section><p class="service-notice">生产就绪：尚未完成。真实身份、外部连接、容量、备份恢复和学校审批需分别验收。</p>`;$('#reloadSystemHealth').onclick=healthAdmin;document.querySelectorAll('[data-feature-flag]').forEach(btn=>btn.onclick=async()=>{const enabled=btn.dataset.enabled==='true';if(!await askConfirm(enabled?'确认恢复受理新单？':'确认暂停该服务新单？已有业务仍可继续办理。'))return;btn.disabled=true;try{await api('admin/feature-flags','PATCH',{code:btn.dataset.featureFlag,enabled});toast('新单开关已更新');healthAdmin()}catch(e){toast(e.message);btn.disabled=false}})}
async function diningFeedbackSummary(){const rows=await api('admin/dining/feedback/summary');$('#content').innerHTML=adminHeading('dining/feedback/summary')+heading('餐饮反馈汇总','仅展示分类、状态与数量，不包含个体反馈正文或学生资料。')+`<section class="card">${rows.map(r=>`<article class="listitem"><div><h3>${esc(diningCategories[r.category]||r.category)}</h3><p>${esc(diningFeedbackStatuses[r.status]||r.status)}</p></div><strong>${r.count} 条</strong></article>`).join('')||'<div class="empty">暂无反馈汇总数据。</div>'}</section>`}
